head.script:
// [샘플 분리]
//  _1 : disabled="true" (생성 시 고정) - @propval true / @spec1 편집 불가 / @spec2 이벤트 미발생 / @spec3 disabledClass 적용
//  _2 : disabled="false" 명시 + disabled 미설정 - @propval false(default)
//  _3 : GridView/Row/Column/Cell 4개 단위 동시 설정 + readOnly 대조 그리드 - @description| 단위별 관리 / @spec4 메소드 규칙 차이

// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > disabled]<br/>특정 Body Cell 이 아닌 Body Column 의 비활성화(disabled) 상태를 설정합니다.",
    "validation" : [
        "false 설정 시, Body Column 의 비활성화(disabled) 상태를 해제합니다.",
        "미설정 시, Body Column 의 비활성화(disabled) 상태를 해제합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 편집 가능한 GridView (gBody 4 Column, editType=text), 데이터 4건
//  - col2 = disabled="false" (명시 해제, 생성 시 고정) / col3 = disabled 미설정 (속성 자체를 부여하지 않음) : con 셀렉트박스 없음
//    · col2 disabled="false" -> 비활성화 해제 (편집 가능, 마우스/키보드 이벤트 발생)
//    · col3 미설정 -> 기본값 false 로 동작 (편집 가능)
//  - col1,col4 는 편집 대조군. 상위 GridView 단위 disabled 미설정(기본 false)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    // label1 이 잔존하면 동일 cID 의 dynamicCreate 가 undefined 를 반환해 라벨이 갱신되지 않는다.
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] col2 의 disabled = false (명시 해제, 생성 시 고정) / col3 은 disabled 속성 미설정 / 상위 GridView 단위 disabled 미설정 / col1,col4 편집 대조\n[절차] col2·col3 셀 더블클릭 -> 편집 진입 확인, 셀 클릭 및 키 입력 -> 이벤트 발생 확인\n[확인] (disabled 상태 확인) 버튼으로 col2·col3 의 getColumnDisabled 와 실효 disabled, 편집 진입 여부 확인"', '', 'label1');

    // dataList 생성 (col1~col4 4컬럼 바인딩)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { col1 : "RowA", col2 : "AAA", col3 : "10", col4 : "TextA" },
        { col1 : "RowB", col2 : "BBB", col3 : "20", col4 : "TextB" },
        { col1 : "RowC", col2 : "CCC", col3 : "30", col4 : "TextC" },
        { col1 : "RowD", col2 : "DDD", col3 : "40", col4 : "TextD" }
    ]);

    // col2 의 disabled 속성 : false (명시 해제, 생성 시 고정). col3 은 disabled 속성 미설정.
    let col2DisabledAttr = ' disabled="false"';

    let eList = $c.gcm.createEList(["oncellclick", "oncelldblclick", "onkeydown"]);

    // target 생성 (편집 가능 그리드 : gBody Column 에 editType="text")
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" focusMode="cell" checkAllType="false" disabledBackgroundColor="#D3D3D3" id="" style="width:480px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="Column disabled 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="col1(편집)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="col2(false)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="col3(미설정)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="col4(편집)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" editType="text"' + col2DisabledAttr + '></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" editType="text"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// disabled 상태 확인 버튼
//  - col2(false 명시) / col3(미설정) 의 Column 단위 설정값과 Cell 에 적용된 실효 상태
//  - 편집 진입 시도(setFocusedCell editMode=true + isEditing) : 두 Column 모두 편집 가능해야 함
scwin.btn_checkDisabled_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("col2(false 명시) getColumnDisabled : " + target1.getColumnDisabled(1) + " / Cell(0,col2) 실효 disabled : " + target1.getDisabled("all", 0, 1));
    bottom.setReturnValue("col3(미설정) getColumnDisabled : " + target1.getColumnDisabled(2) + " / Cell(0,col3) 실효 disabled : " + target1.getDisabled("all", 0, 2));

    // 편집 진입 시도 : col2(false 명시) / col3(미설정)
    let cells = [[0, 1, "Cell(0,col2) [false 명시]"], [0, 2, "Cell(0,col3) [미설정]"]];
    for (let i = 0; i < cells.length; i++) {
        target1.setFocusedCell(cells[i][0], cells[i][1], true);
        bottom.setReturnValue(cells[i][2] + " 편집 진입(isEditing) : " + target1.isEditing());
        target1.setFocusedCell(-1, -1);
    }
}



// 셀 클릭 시 발생
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncellclick 발생 : Cell(" + rowIndex + "," + columnIndex + ") columnId=" + columnId);
}



// 셀 더블클릭 시 발생 (비활성화 해제 상태의 셀은 Edit Mode 진입 -> isEditing=true)
scwin.target1_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    let editing = target1.isEditing();
    wf_body_bottom.getObj("scwin").setReturnValue("oncelldblclick 발생 : Cell(" + rowIndex + "," + columnIndex + ") isEditing=" + editing);
}



// 키다운 시 발생
scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onkeydown 발생 : keyCode=" + (e.keyCode || e.which));
}
